<?php require 'admin_guard.php';require 'admin_db.php';if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['add'])){$s=mysqli_prepare($conn,'INSERT INTO admin_work_due(adminID,title,details) VALUES(?,?,?)');mysqli_stmt_bind_param($s,'sss',$adminID,$_POST['title'],$_POST['details']);mysqli_stmt_execute($s);}elseif(isset($_POST['done'])){$id=(int)$_POST['id'];mysqli_query($conn,"UPDATE admin_work_due SET status='DONE' WHERE workID=$id AND adminID='".mysqli_real_escape_string($conn,$adminID)."'");}elseif(isset($_POST['delete'])){mysqli_query($conn,"DELETE FROM admin_work_due WHERE workID=".(int)$_POST['id']);}}$rows=mysqli_query($conn,"SELECT * FROM admin_work_due WHERE adminID='".mysqli_real_escape_string($conn,$adminID)."' ORDER BY status,created_at DESC");?><!doctype html><html><head><title>Work Due</title><link rel="stylesheet" href="admin_pages.css"></head><body><div class="page"><div class="top"><h1>Work Due</h1><a class="btn" href="admin_dashboard.php">Dashboard</a></div><div class="panel"><form method="post"><input name="title" placeholder="Work title" required><textarea name="details" placeholder="Details" required></textarea><button name="add">Add Work</button></form></div><div class="panel"><table><tr><th>Title</th><th>Details</th><th>Status</th><th>Action</th></tr><?php while($x=mysqli_fetch_assoc($rows)):?><tr><td><?=$x['title']?></td><td><?=$x['details']?></td><td><?=$x['status']?></td><td><form method="post" class="actions"><input type="hidden" name="id" value="<?=$x['workID']?>"><button name="done" class="success">Done</button><button name="delete" class="danger">Delete</button></form></td></tr><?php endwhile;?></table></div></div></body></html>
